// Generated by deno-lifeboat. A replacement for Deno.cron on Node.js and Bun, built on croner.
// Like Deno.cron, schedules are evaluated in UTC and a run is skipped while the previous one is still running.
// Unlike Deno Deploy, this runs in-process: every running instance of your app fires its own jobs.
import { Cron } from "croner";

export type CronScheduleField = number | { exact: number | number[] } | { start?: number; end?: number; every?: number };

export interface CronSchedule {
  minute?: CronScheduleField;
  hour?: CronScheduleField;
  dayOfMonth?: CronScheduleField;
  month?: CronScheduleField;
  dayOfWeek?: CronScheduleField;
}

export interface CronOptions {
  backoffSchedule?: number[];
  signal?: AbortSignal;
}

type CronHandler = () => Promise<void> | void;

export function cron(name: string, schedule: string | CronSchedule, handler: CronHandler): Promise<void>;
export function cron(
  name: string,
  schedule: string | CronSchedule,
  options: CronOptions,
  handler: CronHandler,
): Promise<void>;
export function cron(
  name: string,
  schedule: string | CronSchedule,
  optionsOrHandler: CronOptions | CronHandler,
  maybeHandler?: CronHandler,
): Promise<void> {
  const options: CronOptions = typeof optionsOrHandler === "function" ? {} : optionsOrHandler;
  const handler = typeof optionsOrHandler === "function" ? optionsOrHandler : maybeHandler;
  if (typeof handler !== "function") throw new TypeError(`cron "${name}": a handler function is required`);
  const expression = typeof schedule === "string" ? schedule : scheduleToCron(schedule);
  const backoff = options.backoffSchedule ?? [];
  const job = new Cron(expression, { name, timezone: "UTC", protect: true }, async () => {
    await runWithBackoff(name, handler, backoff);
  });
  return new Promise<void>((resolve) => {
    if (options.signal?.aborted) {
      job.stop();
      resolve();
      return;
    }
    options.signal?.addEventListener(
      "abort",
      () => {
        job.stop();
        resolve();
      },
      { once: true },
    );
  });
}

async function runWithBackoff(name: string, handler: CronHandler, backoff: number[]): Promise<void> {
  for (let attempt = 0; ; attempt++) {
    try {
      await handler();
      return;
    } catch (error) {
      const delay = backoff[attempt];
      if (delay === undefined) {
        console.error(`cron "${name}" failed`, error);
        return;
      }
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
}

function fieldToCron(field: CronScheduleField | undefined): string {
  if (field === undefined) return "*";
  if (typeof field === "number") return String(field);
  if ("exact" in field) return Array.isArray(field.exact) ? field.exact.join(",") : String(field.exact);
  const range = field.start === undefined && field.end === undefined
    ? "*"
    : `${field.start ?? 0}${field.end === undefined ? "" : `-${field.end}`}`;
  return field.every === undefined ? range : `${range}/${field.every}`;
}

export function scheduleToCron(schedule: CronSchedule): string {
  return [schedule.minute, schedule.hour, schedule.dayOfMonth, schedule.month, schedule.dayOfWeek]
    .map(fieldToCron)
    .join(" ");
}
